    circuitSvg: "<svg viewBox=\"0 0 400 220\" class=\"circuit-diagram\">\n  <defs>\n    <pattern id=\"grid_8245\" width=\"20\" height=\"20\" patternUnits=\"userSpaceOnUse\">\n      <circle cx=\"2\" cy=\"2\" r=\"1\" fill=\"#334155\" />\n    </pattern>\n  </defs>\n  <rect width=\"400\" height=\"220\" fill=\"#0f172a\" rx=\"8\" />\n  \n      <path d=\"M 80 80 L 80 40 L 320 40 L 320 180 L 80 180 L 80 120\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      \n    <circle cx=\"80\" cy=\"100\" r=\"18\" stroke=\"#f43f5e\" stroke-width=\"3\" fill=\"#1e293b\" />\n    <text x=\"80\" y=\"97\" fill=\"#f43f5e\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">+</text>\n    <text x=\"80\" y=\"112\" fill=\"#94a3b8\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">−</text>\n    <text x=\"52\" y=\"105\" fill=\"#f87171\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"end\">E₁ = 15V</text>\n  \n      \n    <path d=\"M 160 40 L 166 30 L 178 50 L 190 30 L 202 50 L 214 30 L 220 40\" stroke=\"#fbbf24\" stroke-width=\"3\" fill=\"none\" stroke-linejoin=\"round\" />\n    <text x=\"190\" y=\"22\" fill=\"#fde047\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">V_R1 = 4V</text>\n  \n      \n    <circle cx=\"320\" cy=\"110\" r=\"18\" stroke=\"#f43f5e\" stroke-width=\"3\" fill=\"#1e293b\" />\n    <text x=\"320\" y=\"122\" fill=\"#f43f5e\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">−</text>\n    <text x=\"320\" y=\"107\" fill=\"#94a3b8\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">+</text>\n    <text x=\"292\" y=\"115\" fill=\"#f87171\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"end\">E₂ = 5V</text>\n  \n      \n    <path d=\"M 160 180 L 166 170 L 178 190 L 190 170 L 202 190 L 214 170 L 220 180\" stroke=\"#fbbf24\" stroke-width=\"3\" fill=\"none\" stroke-linejoin=\"round\" />\n    <text x=\"190\" y=\"162\" fill=\"#fde047\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">V_R2 = ?</text>\n  \n    \n</svg>",
