"110\" r=\"4\" fill=\"#38bdf8\" />\n      <circle cx=\"250\" cy=\"110\" r=\"5\" fill=\"#34d399\" /><text x=\"260\" y=\"114\" fill=\"#34d399\" font-size=\"14\" font-weight=\"bold\">C</text>\n      <circle cx=\"150\" cy=\"110\" r=\"5\" fill=\"#34d399\" /><text x=\"130\" y=\"114\" fill=\"#34d399\" font-size=\"14\" font-weight=\"bold\">D</text>\n      <text x=\"200\" y=\"115\" fill=\"#34d399\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">V_CD ?</text>\n      \n    <line x1=\"160\" y1=\"110\" x2=\"240\" y2=\"110\" stroke=\"#34d399\" stroke-width=\"2\" stroke-dasharray=\"3,3\" />\n    <text x=\"210\" y=\"114\" fill=\"#34d399\" font-size=\"13\" font-weight=\"bold\"></text>\n  \n      <text x=\"200\" y=\"30\" fill=\"#94a3b8\" font-size=\"12\">R₁·R₄ = R₂·R₃</text>\n    \n</svg>",
