    circuitSvg: "<svg viewBox=\"0 0 400 220\" class=\"circuit-diagram\">\n  <defs>\n    <pattern id=\"grid_4237\" width=\"20\" height=\"20\" patternUnits=\"userSpaceOnUse\">\n      <circle cx=\"2\" cy=\"2\" r=\"1\" fill=\"#334155\" />\n    </pattern>\n  </defs>\n  <rect width=\"400\" height=\"220\" fill=\"#0f172a\" rx=\"8\" />\n  \n      <rect x=\"50\" y=\"60\" width=\"140\" height=\"100\" stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"#1e293b\" rx=\"6\" />\n      <text x=\"120\" y=\"105\" fill=\"#94a3b8\" font-size=\"12\" text-anchor=\"middle\">Rete con pilotati</text>\n      <text x=\"120\" y=\"125\" fill=\"#94a3b8\" font-size=\"11\" text-anchor=\"middle\">(Indipendenti OFF)</text>\n      <circle cx=\"190\" cy=\"80\" r=\"5\" fill=\"#38bdf8\" /><text x=\"200\" y=\"75\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"bold\">A</text>\n      <circle cx=\"190\" cy=\"140\" r=\"5\" fill=\"#38bdf8\" /><text x=\"200\" y=\"155\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"bold\">B</text>\n      <path d=\"M 190 80 L 270 80 L 270 95\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      \n    <circle cx=\"270\" cy=\"110\" r=\"18\" stroke=\"#f43f5e\" stroke-width=\"3\" fill=\"#1e293b\" />\n    <text x=\"270\" y=\"107\" fill=\"#f43f5e\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">+</text>\n    <text x=\"270\" y=\"122\" fill=\"#94a3b8\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">−</text>\n    <text x=\"242\" y=\"115\" fill=\"#f87171\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"end\">10 V</text>\n  \n      <path d=\"M 270 125 L 270 140 L 190 140\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      <polygon points=\"230,75 220,80 230,85\" fill=\"#34d399\" />\n      <text x=\"235\" y=\"70\" fill=\"#34d399\" font-size=\"11\" font-weight=\"bold\">I_test = 2 A</text>\n    \n</svg>",
    correctAnswer: 5,
    unit: "Ω",
    explanation: "\n      <strong>💡 Trucco mentale per la palestra:</strong><br>\n      • Definizione di resistenza equivalente con generatore di prova:<br>\n      <code>R_th = V_test / I_test = 10 V / 2 A = 5 Ω</code>.\n    "
