    circuitSvg: "<svg viewBox=\"0 0 400 220\" class=\"circuit-diagram\">\n  <defs>\n    <pattern id=\"grid_54867\" width=\"20\" height=\"20\" patternUnits=\"userSpaceOnUse\">\n      <circle cx=\"2\" cy=\"2\" r=\"1\" fill=\"#334155\" />\n    </pattern>\n  </defs>\n  <rect width=\"400\" height=\"220\" fill=\"#0f172a\" rx=\"8\" />\n  \n      \n    <polygon points=\"200,85 200,155 265,120\" stroke=\"#a855f7\" stroke-width=\"3\" fill=\"#1e293b\" />\n    <text x=\"208\" y=\"106\" fill=\"#f43f5e\" font-size=\"14\" font-weight=\"bold\">−</text>\n    <text x=\"208\" y=\"142\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"bold\">+</text>\n    <text x=\"226\" y=\"124\" fill=\"#c084fc\" font-size=\"11\" font-weight=\"bold\">Op-Amp</text>\n  \n      <path d=\"M 60 70 L 100 70\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      \n    <path d=\"M 100 70 L 105 60 L 115 80 L 125 60 L 135 80 L 145 60 L 150 70\" stroke=\"#fbbf24\" stroke-width=\"3\" fill=\"none\" stroke-linejoin=\"round\" />\n    <text x=\"125\" y=\"52\" fill=\"#fde047\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">5 kΩ</text>\n  \n      <path d=\"M 150 70 L 180 70 L 180 95 L 200 95\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      <text x=\"50\" y=\"75\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"end\">V₁ = 2V</text>\n      <path d=\"M 60 110 L 100 110\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      \n    <path d=\"M 100 110 L 105 100 L 115 120 L 125 100 L 135 120 L 145 100 L 150 110\" stroke=\"#fbbf24\" stroke-width=\"3\" fill=\"none\" stroke-linejoin=\"round\" />\n    <text x=\"125\" y=\"92\" fill=\"#fde047\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">10 kΩ</text>\n  \n      <path d=\"M 150 110 L 180 110\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      <text x=\"50\" y=\"115\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"end\">V₂ = 3V</text>\n      <circle cx=\"180\" cy=\"95\" r=\"4\" fill=\"#38bdf8\" />\n      <!-- Feedback Rf -->\n      <path d=\"M 180 95 L 180 40 L 200 40\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      \n    <path d=\"M 200 40 L 206 30 L 218 50 L 230 30 L 242 50 L 254 30 L 260 40\" stroke=\"#fbbf24\" stroke-width=\"3\" fill=\"none\" stroke-linejoin=\"round\" />\n    <text x=\"230\" y=\"22\" fill=\"#fde047\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">Rf = 10 kΩ</text>\n  \n      <path d=\"M 260 40 L 290 40 L 290 120 L 265 120\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      <path d=\"M 265 120 L 330 120\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      <circle cx=\"330\" cy=\"120\" r=\"5\" fill=\"#34d399\" /><text x=\"340\" y=\"125\" fill=\"#34d399\" font-size=\"14\" font-weight=\"bold\">V_out ?</text>\n      <!-- Ground on + -->\n      <path d=\"M 200 145 L 200 170\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      \n    <line x1=\"185\" y1=\"170\" x2=\"215\" y2=\"170\" stroke=\"#94a3b8\" stroke-width=\"3\" />\n    <line x1=\"190\" y1=\"175\" x2=\"210\" y2=\"175\" stroke=\"#94a3b8\" stroke-width=\"2.5\" />\n    <line x1=\"195\" y1=\"180\" x2=\"205\" y2=\"180\" stroke=\"#94a3b8\" stroke-width=\"2\" />\n  \n    \n</svg>",
    correctAnswer: -7,
    unit: "V",
    explanation: "\n      <strong>💡 Trucco mentale per la palestra:</strong><br>\n      • Guadagno per il primo canale: <code>-Rf / R₁ = -10 / 5 = -2</code> ➔ <code>-2 × 2 V = -4 V</code>.<br>\n      • Guadagno per il secondo canale: <code>-Rf / R₂ = -10 / 10 = -1</code> ➔ <code>-1 × 3 V = -3 V</code>.<br>\n      • Somma algebrica: <code>V_out = -4 + (-3) = -7 V</code>!\n    "
