    circuitSvg: "<svg viewBox=\"0 0 400 220\" class=\"circuit-diagram\">\n  <defs>\n    <pattern id=\"grid_85244\" width=\"20\" height=\"20\" patternUnits=\"userSpaceOnUse\">\n      <circle cx=\"2\" cy=\"2\" r=\"1\" fill=\"#334155\" />\n    </pattern>\n  </defs>\n  <rect width=\"400\" height=\"220\" fill=\"#0f172a\" rx=\"8\" />\n  \n      \n    <polygon points=\"190,75 190,145 255,110\" stroke=\"#a855f7\" stroke-width=\"3\" fill=\"#1e293b\" />\n    <text x=\"198\" y=\"96\" fill=\"#f43f5e\" font-size=\"14\" font-weight=\"bold\">−</text>\n    <text x=\"198\" y=\"132\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"bold\">+</text>\n    <text x=\"216\" y=\"114\" fill=\"#c084fc\" font-size=\"11\" font-weight=\"bold\">Non-Inv</text>\n  \n      <path d=\"M 80 145 L 190 145\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      <text x=\"70\" y=\"150\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"end\">V_in = 2V</text>\n      <path d=\"M 190 75 L 160 75 L 160 115\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      \n    <path d=\"M 160 115 L 150 119 L 170 127 L 150 135 L 170 143 L 150 151 L 160 155\" stroke=\"#fbbf24\" stroke-width=\"3\" fill=\"none\" stroke-linejoin=\"round\" />\n    <text x=\"178\" y=\"139\" fill=\"#fde047\" font-size=\"12\" font-weight=\"bold\">R₁ = 4k</text>\n  \n      <path d=\"M 160 155 L 160 175\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      \n    <line x1=\"145\" y1=\"175\" x2=\"175\" y2=\"175\" stroke=\"#94a3b8\" stroke-width=\"3\" />\n    <line x1=\"150\" y1=\"180\" x2=\"170\" y2=\"180\" stroke=\"#94a3b8\" stroke-width=\"2.5\" />\n    <line x1=\"155\" y1=\"185\" x2=\"165\" y2=\"185\" stroke=\"#94a3b8\" stroke-width=\"2\" />\n  \n      <circle cx=\"160\" cy=\"75\" r=\"4\" fill=\"#38bdf8\" />\n      <path d=\"M 160 75 L 160 35 L 200 35\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      \n    <path d=\"M 200 35 L 206 25 L 218 45 L 230 25 L 242 45 L 254 25 L 260 35\" stroke=\"#fbbf24\" stroke-width=\"3\" fill=\"none\" stroke-linejoin=\"round\" />\n    <text x=\"230\" y=\"17\" fill=\"#fde047\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">Rf = 12 kΩ</text>\n  \n      <path d=\"M 260 35 L 290 35 L 290 110 L 255 110\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      <path d=\"M 255 110 L 330 110\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      <circle cx=\"330\" cy=\"110\" r=\"5\" fill=\"#34d399\" /><text x=\"340\" y=\"115\" fill=\"#34d399\" font-size=\"14\" font-weight=\"bold\">V_out ?</text>\n    \n</svg>",
    correctAnswer: 8,
