    circuitSvg: "<svg viewBox=\"0 0 400 220\" class=\"circuit-diagram\">\n  <defs>\n    <pattern id=\"grid_26791\" width=\"20\" height=\"20\" patternUnits=\"userSpaceOnUse\">\n      <circle cx=\"2\" cy=\"2\" r=\"1\" fill=\"#334155\" />\n    </pattern>\n  </defs>\n  <rect width=\"400\" height=\"220\" fill=\"#0f172a\" rx=\"8\" />\n  \n      <path d=\"M 70 80 L 70 40 L 140 40\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      \n    <circle cx=\"70\" cy=\"110\" r=\"18\" stroke=\"#f43f5e\" stroke-width=\"3\" fill=\"#1e293b\" />\n    <text x=\"70\" y=\"107\" fill=\"#f43f5e\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">+</text>\n    <text x=\"70\" y=\"122\" fill=\"#94a3b8\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">−</text>\n    <text x=\"42\" y=\"115\" fill=\"#f87171\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"end\">12 V</text>\n  \n      <!-- Diode pointing left (opposing E) -->\n      \n    <polygon points=\"160,28 160,52 140,40\" fill=\"#f43f5e\" />\n    <line x1=\"140\" y1=\"28\" x2=\"140\" y2=\"52\" stroke=\"#f43f5e\" stroke-width=\"3\" />\n    <text x=\"150\" y=\"22\" fill=\"#f87171\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">D (OFF)</text>\n  \n      <path d=\"M 160 40 L 220 40\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      \n    <path d=\"M 220 40 L 226 30 L 238 50 L 250 30 L 262 50 L 274 30 L 280 40\" stroke=\"#fbbf24\" stroke-width=\"3\" fill=\"none\" stroke-linejoin=\"round\" />\n    <text x=\"250\" y=\"22\" fill=\"#fde047\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">R = 6 Ω</text>\n  \n      <path d=\"M 280 40 L 330 40 L 330 170 L 70 170 L 70 130\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      <text x=\"200\" y=\"115\" fill=\"#f87171\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">Polarizzazione Inversa</text>\n    \n</svg>",
