"#fde047\" font-size=\"12\" font-weight=\"bold\">R</text>\n  \n      <path d=\"M 260 140 L 260 165\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      \n    <line x1=\"245\" y1=\"165\" x2=\"275\" y2=\"165\" stroke=\"#94a3b8\" stroke-width=\"3\" />\n    <line x1=\"250\" y1=\"170\" x2=\"270\" y2=\"170\" stroke=\"#94a3b8\" stroke-width=\"2.5\" />\n    <line x1=\"255\" y1=\"175\" x2=\"265\" y2=\"175\" stroke=\"#94a3b8\" stroke-width=\"2\" />\n  \n      <path d=\"M 260 100 L 330 100\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      <circle cx=\"330\" cy=\"100\" r=\"5\" fill=\"#34d399\" /><text x=\"340\" y=\"105\" fill=\"#34d399\" font-size=\"14\" font-weight=\"bold\">V_out ?</text>\n    \n</svg>",
