    circuitSvg: "<svg viewBox=\"0 0 400 220\" class=\"circuit-diagram\">\n  <defs>\n    <pattern id=\"grid_64736\" width=\"20\" height=\"20\" patternUnits=\"userSpaceOnUse\">\n      <circle cx=\"2\" cy=\"2\" r=\"1\" fill=\"#334155\" />\n    </pattern>\n  </defs>\n  <rect width=\"400\" height=\"220\" fill=\"#0f172a\" rx=\"8\" />\n  \n      \n    <circle cx=\"70\" cy=\"110\" r=\"18\" stroke=\"#38bdf8\" stroke-width=\"3\" fill=\"#1e293b\" />\n    <path d=\"M 61 110 Q 65.5 103 70 110 T 79 110\" stroke=\"#38bdf8\" stroke-width=\"2.5\" fill=\"none\" />\n    <text x=\"42\" y=\"115\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"end\">50 V_eff</text>\n  \n      <path d=\"M 70 80 L 70 40 L 260 40 L 260 80\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      <rect x=\"235\" y=\"80\" width=\"50\" height=\"60\" stroke=\"#fbbf24\" stroke-width=\"2.5\" fill=\"#1e293b\" rx=\"4\" />\n      <text x=\"260\" y=\"115\" fill=\"#fde047\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">|Z|=10Ω</text>\n      <path d=\"M 260 140 L 260 170 L 70 170 L 70 130\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      <polygon points=\"170,35 180,40 170,45\" fill=\"#34d399\" />\n      <text x=\"175\" y=\"25\" fill=\"#34d399\" font-size=\"12\" font-weight=\"bold\">I_eff = ?</text>\n    \n</svg>",
