    circuitSvg: "<svg viewBox=\"0 0 400 220\" class=\"circuit-diagram\">\n  <defs>\n    <pattern id=\"grid_45197\" width=\"20\" height=\"20\" patternUnits=\"userSpaceOnUse\">\n      <circle cx=\"2\" cy=\"2\" r=\"1\" fill=\"#334155\" />\n    </pattern>\n  </defs>\n  <rect width=\"400\" height=\"220\" fill=\"#0f172a\" rx=\"8\" />\n  \n      \n    <circle cx=\"60\" cy=\"110\" r=\"18\" stroke=\"#38bdf8\" stroke-width=\"3\" fill=\"#1e293b\" />\n    <path d=\"M 51 110 Q 55.5 103 60 110 T 69 110\" stroke=\"#38bdf8\" stroke-width=\"2.5\" fill=\"none\" />\n    <text x=\"32\" y=\"115\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"end\">100 V</text>\n  \n      <path d=\"M 60 80 L 60 50 L 130 50\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      \n    <path d=\"M 130 50 L 136 40 L 148 60 L 160 40 L 172 60 L 184 40 L 190 50\" stroke=\"#fbbf24\" stroke-width=\"3\" fill=\"none\" stroke-linejoin=\"round\" />\n    <text x=\"160\" y=\"32\" fill=\"#fde047\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">R = 4 Ω</text>\n  \n      <path d=\"M 190 50 L 230 50\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      \n    <path d=\"M 230 50 C 240 30 250 30 255 50 C 265 30 275 30 280 50 C 290 30 300 30 305 50\" stroke=\"#34d399\" stroke-width=\"3\" fill=\"none\" />\n    <text x=\"268\" y=\"68\" fill=\"#34d399\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">X_L = 3 Ω</text>\n  \n      <path d=\"M 305 50 L 340 50 L 340 160 L 60 160 L 60 130\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      \n    <line x1=\"130\" y1=\"90\" x2=\"190\" y2=\"90\" stroke=\"#34d399\" stroke-width=\"2\" stroke-dasharray=\"3,3\" />\n    <text x=\"170\" y=\"94\" fill=\"#34d399\" font-size=\"13\" font-weight=\"bold\">V_R = ?</text>\n  \n    \n</svg>",
