    circuitSvg: "<svg viewBox=\"0 0 400 220\" class=\"circuit-diagram\">\n  <defs>\n    <pattern id=\"grid_88168\" width=\"20\" height=\"20\" patternUnits=\"userSpaceOnUse\">\n      <circle cx=\"2\" cy=\"2\" r=\"1\" fill=\"#334155\" />\n    </pattern>\n  </defs>\n  <rect width=\"400\" height=\"220\" fill=\"#0f172a\" rx=\"8\" />\n  \n      <circle cx=\"200\" cy=\"110\" r=\"25\" stroke=\"#34d399\" stroke-width=\"3\" fill=\"#1e293b\" />\n      <text x=\"200\" y=\"118\" fill=\"#34d399\" font-size=\"20\" font-weight=\"bold\" text-anchor=\"middle\">V</text>\n      <path d=\"M 200 40 L 200 85\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      <path d=\"M 200 135 L 200 180\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      <circle cx=\"200\" cy=\"40\" r=\"5\" fill=\"#34d399\" /><text x=\"210\" y=\"45\" fill=\"#34d399\" font-size=\"14\" font-weight=\"bold\">+</text>\n      <circle cx=\"200\" cy=\"180\" r=\"5\" fill=\"#94a3b8\" /><text x=\"210\" y=\"185\" fill=\"#94a3b8\" font-size=\"14\" font-weight=\"bold\">−</text>\n      <text x=\"290\" y=\"115\" fill=\"#fde047\" font-size=\"13\" font-weight=\"bold\">R_int = ?</text>\n    \n</svg>",
