" font-weight=\"bold\">+</text>\n    <text x=\"216\" y=\"114\" fill=\"#c084fc\" font-size=\"11\" font-weight=\"bold\">Buffer</text>\n  \n      <path d=\"M 255 110 L 320 110\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      <circle cx=\"290\" cy=\"110\" r=\"4\" fill=\"#38bdf8\" />\n      <path d=\"M 290 110 L 290 50 L 190 50 L 190 75\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      <circle cx=\"320\" cy=\"110\" r=\"5\" fill=\"#34d399\" /><text x=\"330\" y=\"115\" fill=\"#34d399\" font-size=\"14\" font-weight=\"bold\">V_out ?</text>\n    \n</svg>",
