    question: "Calcola la pulsazione di risonanza propria ω₀ = 1 / √(L × C) in rad/s di un circuito RLC con L = 20 mH (0.02 H) e C = 50 µF (5 × 10⁻⁵ F).",
    circuitSvg: "\n      <svg viewBox=\"0 0 420 200\" class=\"circuit-diagram\">\n        <rect width=\"420\" height=\"200\" fill=\"#0f172a\" rx=\"8\" />\n\n        <!-- Source -->\n        <circle cx=\"50\" cy=\"100\" r=\"20\" stroke=\"#38bdf8\" stroke-width=\"3\" fill=\"#1e293b\" />\n        <path d=\"M 40 100 Q 45 92 50 100 T 60 100\" stroke=\"#38bdf8\" stroke-width=\"2.5\" fill=\"none\" />\n\n        <!-- Top Wire with R, L, C in series -->\n        <path d=\"M 50 80 L 50 40 L 90 40\" stroke=\"#38bdf8\" stroke-width=\"3\" fill=\"none\" />\n\n        <!-- R -->\n        <path d=\"M 90 40 L 95 30 L 105 50 L 115 30 L 125 50 L 135 30 L 140 40 L 170 40\" stroke=\"#fbbf24\" stroke-width=\"3\" fill=\"none\" stroke-linejoin=\"round\" />\n        <text x=\"110\" y=\"20\" fill=\"#fde047\" font-size=\"12\" font-weight=\"bold\">R</text>\n\n        <!-- L -->\n        <path d=\"M 170 40 C 180 20 195 20 200 40 C 210 20 225 20 230 40 C 240 20 255 20 260 40 L 280 40\" stroke=\"#34d399\" stroke-width=\"3\" fill=\"none\" />\n        <text x=\"200\" y=\"65\" fill=\"#34d399\" font-size=\"12\" font-weight=\"bold\">L = 20 mH</text>\n\n        <!-- C -->\n        <line x1=\"295\" y1=\"25\" x2=\"295\" y2=\"55\" stroke=\"#38bdf8\" stroke-width=\"4\" />\n        <line x1=\"305\" y1=\"25\" x2=\"305\" y2=\"55\" stroke=\"#38bdf8\" stroke-width=\"4\" />\n        <path d=\"M 280 40 L 295 40\" stroke=\"#38bdf8\" stroke-width=\"3\" fill=\"none\" />\n        <path d=\"M 305 40 L 370 40 L 370 160 L 50 160 L 50 120\" stroke=\"#38bdf8\" stroke-width=\"3\" fill=\"none\" />\n        <text x=\"320\" y=\"35\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">C = 50 µF</text>\n      </svg>\n    ",
