    circuitSvg: "\n      <svg viewBox=\"0 0 420 220\" class=\"circuit-diagram\">\n        <rect width=\"420\" height=\"220\" fill=\"#0f172a\" rx=\"8\" />\n\n        <!-- Star Load Center Node -->\n        <circle cx=\"210\" cy=\"110\" r=\"5\" fill=\"#94a3b8\" />\n        <text x=\"220\" y=\"115\" fill=\"#94a3b8\" font-size=\"12\">O</text>\n\n        <!-- Branch 1 (top) -->\n        <path d=\"M 210 110 L 210 85 L 200 80 L 220 72 L 200 64 L 220 56 L 210 50 L 210 30\" stroke=\"#fbbf24\" stroke-width=\"3\" fill=\"none\" stroke-linejoin=\"round\" />\n        <text x=\"230\" y=\"65\" fill=\"#fde047\" font-size=\"12\" font-weight=\"bold\">R = 20 Ω</text>\n        <circle cx=\"210\" cy=\"30\" r=\"4\" fill=\"#ef4444\" />\n        <text x=\"180\" y=\"30\" fill=\"#ef4444\" font-size=\"12\" font-weight=\"bold\">E₁ = 20V</text>\n\n        <!-- Branch 2 (bottom left) -->\n        <path d=\"M 210 110 L 140 150\" stroke=\"#fbbf24\" stroke-width=\"3\" fill=\"none\" />\n        <circle cx=\"140\" cy=\"150\" r=\"4\" fill=\"#3b82f6\" />\n        <text x=\"70\" y=\"155\" fill=\"#3b82f6\" font-size=\"12\" font-weight=\"bold\">E₂ = 20V</text>\n\n        <!-- Branch 3 (bottom right) -->\n        <path d=\"M 210 110 L 280 150\" stroke=\"#fbbf24\" stroke-width=\"3\" fill=\"none\" />\n        <circle cx=\"280\" cy=\"150\" r=\"4\" fill=\"#10b981\" />\n        <text x=\"295\" y=\"155\" fill=\"#10b981\" font-size=\"12\" font-weight=\"bold\">E₃ = 20V</text>\n      </svg>\n    ",
