    circuitSvg: "<svg viewBox=\"0 0 400 220\" class=\"circuit-diagram\">\n  <defs>\n    <pattern id=\"grid_43487\" width=\"20\" height=\"20\" patternUnits=\"userSpaceOnUse\">\n      <circle cx=\"2\" cy=\"2\" r=\"1\" fill=\"#334155\" />\n    </pattern>\n  </defs>\n  <rect width=\"400\" height=\"220\" fill=\"#0f172a\" rx=\"8\" />\n  \n      \n    <circle cx=\"60\" cy=\"110\" r=\"18\" stroke=\"#38bdf8\" stroke-width=\"3\" fill=\"#1e293b\" />\n    <path d=\"M 51 110 Q 55.5 103 60 110 T 69 110\" stroke=\"#38bdf8\" stroke-width=\"2.5\" fill=\"none\" />\n    <text x=\"32\" y=\"115\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"end\">e_th</text>\n  \n      <path d=\"M 60 80 L 60 50 L 130 50\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      <rect x=\"130\" y=\"35\" width=\"80\" height=\"30\" stroke=\"#f43f5e\" stroke-width=\"2\" fill=\"#1e293b\" rx=\"4\" />\n      <text x=\"170\" y=\"55\" fill=\"#f87171\" font-size=\"11\" font-weight=\"bold\" text-anchor=\"middle\">4 + j3 Ω</text>\n      <path d=\"M 210 50 L 260 50 L 260 80\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n      <rect x=\"230\" y=\"80\" width=\"60\" height=\"60\" stroke=\"#34d399\" stroke-width=\"2.5\" fill=\"#1e293b\" rx=\"4\" />\n      <text x=\"260\" y=\"115\" fill=\"#34d399\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">Z_L = ?</text>\n      <path d=\"M 260 140 L 260 170 L 60 170 L 60 130\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n    \n</svg>",
