    circuitSvg: "<svg viewBox=\"0 0 400 220\" class=\"circuit-diagram\">\n  <defs>\n    <pattern id=\"grid_56483\" width=\"20\" height=\"20\" patternUnits=\"userSpaceOnUse\">\n      <circle cx=\"2\" cy=\"2\" r=\"1\" fill=\"#334155\" />\n    </pattern>\n  </defs>\n  <rect width=\"400\" height=\"220\" fill=\"#0f172a\" rx=\"8\" />\n  \n  <!-- Thévenin AC generator -->\n  \n    <circle cx=\"60\" cy=\"110\" r=\"18\" stroke=\"#38bdf8\" stroke-width=\"3\" fill=\"#1e293b\" />\n    <path d=\"M 51 110 Q 55.5 103 60 110 T 69 110\" stroke=\"#38bdf8\" stroke-width=\"2.5\" fill=\"none\" />\n    <text x=\"32\" y=\"115\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"end\">V_th = 20V</text>\n  \n  <path d=\"M 60 80 L 60 55 L 110 55\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n  <!-- Internal impedance Z_th = 4 + j3 -->\n  <rect x=\"110\" y=\"38\" width=\"80\" height=\"34\" stroke=\"#f43f5e\" stroke-width=\"2\" fill=\"#1e293b\" rx=\"4\" />\n  <text x=\"150\" y=\"59\" fill=\"#f87171\" font-size=\"11\" font-weight=\"bold\" text-anchor=\"middle\">Z_th = 4+j3 Ω</text>\n  <path d=\"M 190 55 L 250 55\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n  <circle cx=\"250\" cy=\"55\" r=\"5\" fill=\"#38bdf8\" /><text x=\"245\" y=\"45\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"bold\">A</text>\n  <path d=\"M 250 55 L 290 55 L 290 75\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n  <!-- Load impedance Z_L -->\n  <rect x=\"260\" y=\"75\" width=\"80\" height=\"45\" stroke=\"#34d399\" stroke-width=\"2.5\" fill=\"#1e293b\" rx=\"4\" />\n  <text x=\"300\" y=\"97\" fill=\"#34d399\" font-size=\"11\" font-weight=\"bold\" text-anchor=\"middle\">Z_L = 4−j3 Ω</text>\n  <text x=\"300\" y=\"112\" fill=\"#94a3b8\" font-size=\"9\" text-anchor=\"middle\">(Adattato)</text>\n  <path d=\"M 290 120 L 290 165 L 250 165\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n  <circle cx=\"250\" cy=\"165\" r=\"5\" fill=\"#38bdf8\" /><text x=\"245\" y=\"183\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"bold\">B</text>\n  <path d=\"M 250 165 L 60 165 L 60 130\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n  <text x=\"200\" y=\"200\" fill=\"#fde047\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\">P_max = V_th² / (4 · R_th) = ?</text>\n\n</svg>",
