    circuitSvg: "<svg viewBox=\"0 0 400 220\" class=\"circuit-diagram\">\n  <defs>\n    <pattern id=\"grid_68057\" width=\"20\" height=\"20\" patternUnits=\"userSpaceOnUse\">\n      <circle cx=\"2\" cy=\"2\" r=\"1\" fill=\"#334155\" />\n    </pattern>\n  </defs>\n  <rect width=\"400\" height=\"220\" fill=\"#0f172a\" rx=\"8\" />\n  \n  \n    <circle cx=\"60\" cy=\"110\" r=\"18\" stroke=\"#38bdf8\" stroke-width=\"3\" fill=\"#1e293b\" />\n    <path d=\"M 51 110 Q 55.5 103 60 110 T 69 110\" stroke=\"#38bdf8\" stroke-width=\"2.5\" fill=\"none\" />\n    <text x=\"32\" y=\"115\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"end\">V</text>\n  \n  <path d=\"M 60 80 L 60 55 L 110 55\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n  \n    <circle cx=\"130\" cy=\"55\" r=\"17\" stroke=\"#f59e0b\" stroke-width=\"2.5\" fill=\"#1e293b\" />\n    <text x=\"130\" y=\"60\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">P</text>\n  \n  <path d=\"M 150 55 L 180 55 L 180 85\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n  <rect x=\"155\" y=\"85\" width=\"50\" height=\"50\" stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"#1e293b\" rx=\"4\" />\n  <text x=\"180\" y=\"112\" fill=\"#38bdf8\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">Carico</text>\n  <path d=\"M 180 135 L 180 165 L 60 165 L 60 130\" stroke=\"#38bdf8\" stroke-width=\"3\"  fill=\"none\" />\n  <!-- Power triangle P=1200, Q=1600, S=2000 -->\n  \n    <polygon points=\"235,140 340,140 340,60\" stroke=\"#38bdf8\" stroke-width=\"2.5\" fill=\"rgba(56, 189, 248, 0.1)\" stroke-linejoin=\"round\" />\n    <polyline points=\"330,140 330,130 340,130\" stroke=\"#94a3b8\" stroke-width=\"1.5\" fill=\"none\" />\n    <path d=\"M 255 140 A 20 20 0 0 0 252 130\" stroke=\"#fde047\" stroke-width=\"1.5\" fill=\"none\" />\n    <text x=\"259\" y=\"136\" fill=\"#fde047\" font-size=\"10\" font-weight=\"bold\">φ</text>\n    <text x=\"287.5\" y=\"156\" fill=\"#fde047\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">P = 1200 W</text>\n    <text x=\"348\" y=\"104\" fill=\"#34d399\" font-size=\"12\" font-weight=\"bold\">Q = ?</text>\n    <text x=\"279.5\" y=\"92\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">|S|</text>\n  \n  <text x=\"200\" y=\"195\" fill=\"#fde047\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">cos(φ)=0.6 ⟹ tan(φ)=4/3 ⟹ Q = 1600 VAR</text>\n\n</svg>",
